"""Set only BumbleBee's native Battle Grade to20 on the isolated test VM."""
import base64
import os
from pathlib import Path
import subprocess
import sys

VM_UUID='7632fb78-37a0-f645-97c0-dc322c50b002'
SQL_BASE64=''


def decode(raw):
    if raw.startswith((b'\xff\xfe',b'\xfe\xff')):return raw.decode('utf-16',errors='replace')
    if b'\0' in raw[:100]:return raw.decode('utf-16-le',errors='replace')
    return raw.decode('utf-8-sig',errors='replace')


def main():
    if sys.argv[1:]!=['--apply']:raise RuntimeError('EXPLICIT_APPLY_REQUIRED')
    if os.geteuid()!=0 or Path('/sys/class/dmi/id/product_uuid').read_text().strip().lower()!=VM_UUID:
        raise RuntimeError('WRONG_TEST_VM_OR_ROOT_REQUIRED; NOTHING_CHANGED')
    sql=base64.b64decode(SQL_BASE64,validate=True)
    shell='''set +x
export SQLCMDPASSWORD="${MSSQL_SA_PASSWORD:-${SA_PASSWORD:-}}"
[ -n "$SQLCMDPASSWORD" ] || exit 2
tool=/opt/mssql-tools18/bin/sqlcmd
[ -x "$tool" ] || tool=/opt/mssql-tools/bin/sqlcmd
exec "$tool" -S localhost -U sa -N -C -d Server01 -b -l 5 -t 30 -h -1 -W -w 65535 -i /dev/stdin
'''
    p=subprocess.run(['docker','exec','-i','sql_main','sh','-ec',shell],input=sql,capture_output=True,timeout=45)
    text=decode(p.stdout+p.stderr)
    for line in text.splitlines():
        if line.startswith(('BUMBLEBEE_','Msg ')) or any(s in line for s in ('NOTHING_CHANGED','CLOSE_GAME','FAILED','DIFFERS','MISSING','Invalid column','Invalid object')):
            print(line[:500],flush=True)
    if p.returncode or not any(s in text for s in ('BUMBLEBEE_GRADE20_APPLIED;','BUMBLEBEE_GRADE20_ALREADY_SET;')):
        raise RuntimeError('GRADE20_NOT_CONFIRMED; KEEP_OUTPUT')
    print('BUMBLEBEE_GRADE20_CONFIRMED; NEXT_LOGIN; NO_SERVICE_RESTART',flush=True)


if __name__=='__main__':
    try:main()
    except Exception as e:
        print('BUMBLEBEE_GRADE20_STOPPED; '+str(e),flush=True)
        raise SystemExit(1)
